/* Lot 100: names, hwb() and color-mix() in registered <color> values (interp, add, match) (generated by scripts/lot100_colorgen.py; expectations from scripts/lot100_colormodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;
static char g_o[160];

static int syn(const char *s) {
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(s, (int)strlen(s), &g_p);
    return g_p.syntax != 0;
}

/* the interpolated text of two colours; the return code is checked */
static const char *ip(const char *a, const char *b, int t, int code) {
    if (!syn("'<color>'")) return "BAD SYNTAX";
    if (wf_cssprop_interp(&g_p, a, b, t, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

/* the sum text; the return code is checked */
static const char *ad(const char *under, const char *v, int code) {
    if (!syn("'<color>'")) return "BAD SYNTAX";
    if (wf_cssprop_add(&g_p, under, v, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

/* whether a '<color>' registration matches v */
static int mt(const char *v) {
    if (!syn("'<color>'")) return -1;
    return wf_cssprop_match_prop(&g_p, v) != 0;
}

static void test_l100_mix_0(void) {
    TEST_ASSERT_EQUAL_STRING("rgb(221, 17, 170)", ip("#d1a", "color-mix(in srgb,hsl(195.2599grad, 74.5%, 5.8%, 99.99%) 94.05%,hwb(358.564grad 82 24 /0.5))", 4, 2));
    TEST_ASSERT_EQUAL_STRING("rgb(50, 64, 63)", ip("black", "color-mix(in srgb , rgb(166, 205, 196) , lightskyblue 11.43%)", 3097, 2));
    TEST_ASSERT_EQUAL_STRING("rgb(168, 120, 130)", ip("azure", "hwb(348.9 0% 58.82%)", 5303, 2));
    TEST_ASSERT_EQUAL_STRING("rgb(46, 117, 33)", ip("hwb(-263.313grad 24% 100%)", "color-mix(in srgb , color-mix(in srgb,darkslategrey,red) 21% , color-mix(in srgb, lime, 14.0143% hwb(5.6638rad 12 61)))", 5000, 2));
    TEST_ASSERT_EQUAL_STRING("rgb(77, 121, 99)", ip("hwb(720deg 50% 87.6%)", "#486", 6546, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(189, 190, 133, 0.8039)", ip("hsl(-0.3turn 34.9% 15.4 / 100%)", "#bdbe85cd", 9999, 2));
    TEST_ASSERT_EQUAL_STRING("rgb(103, 103, 103)", ip("hwb(-668.9 54 29.541% / 1)", "hwb(73 65.5% 96.36%)", 9999, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(139, 145, 120, 0.9363)", ip("color-mix(in srgb,rgba(196, 276, 70%, -0.5),97% hsla(95 0% 32% / 150%))", "color-mix(in srgb , color-mix(in srgb,color-mix(in	srgb , gold , 65% #1c56),hsla(88 8.2% 48.08%)) , lightyellow)", 5000, 2));
    TEST_ASSERT_EQUAL_STRING("rgba(79, 86, 60, 0.8)", ip("color-mix(in srgb , rgba(104, 204, 98%, 0.5) , red)", "color-mix(in srgb,hsl(7.614rad 28.4 52%) 30%,50% hsl(0rad, 0%, 14.8%, 100%))", 9999, 2));
    TEST_ASSERT_EQUAL_STRING("rgb(205, 192, 176)", ip("hwb(-60deg 78% 50%)", "bisque", 5000, 2));
}

